//! Purpose:
//! Builds the catalogued GNU MP release as one static position-independent C archive.
//!
//! Called from:
//! - `crate::native_deps::recipe::CuratedRecipes` for gmp recipe revision 2.
//!
//! Key details:
//! - GMP's `gmp.h` is generated by `configure` from `gmp-h.in`, so the retained header
//!   comes from the build tree rather than the source tree.
//! - The library is built without shared objects; `make` leaves the archive in
//!   `.libs/libgmp.a` even for this static-only configuration.
//! - Cross builds pass the normalized Autoconf host, exactly like the zlib and PCRE2
//!   recipes, because Apple SDK-qualified triples are not `config.sub` inputs.

use std::fs;
use std::path::Path;

use crate::codegen_support::platform::{AppleVariant, Arch, Target};

use super::super::error::NativeError;
use super::super::recipe::RecipeRequest;
use super::super::toolchain::run_checked;
use super::util::{copy_regular, require_regular};

/// Builds libgmp into the catalog-declared staging prefix.
pub fn build(request: &RecipeRequest<'_>) -> Result<(), NativeError> {
    let build = request.staging_prefix.join("build");
    let include = request.staging_prefix.join("include");
    let library = request.staging_prefix.join("lib");
    fs::create_dir_all(&build)
        .map_err(|error| NativeError::io("create gmp build directory", &build, error))?;
    fs::create_dir_all(&include)
        .map_err(|error| NativeError::io("create gmp include directory", &include, error))?;
    fs::create_dir_all(&library)
        .map_err(|error| NativeError::io("create gmp library directory", &library, error))?;

    let configure = request.source.join("configure");
    require_regular("gmp", &configure)?;
    let mut command = request.toolchain.command(Path::new("/bin/sh"));
    command
        .current_dir(&build)
        .arg(&configure)
        .args(configure_args(request.target));
    if request.target != Target::detect_host() {
        command.arg(format!("--host={}", request.toolchain.autoconf_host()));
    }
    run_checked(&mut command, "configure trusted gmp recipe")?;

    let mut make = request.toolchain.command(Path::new("make"));
    make.current_dir(&build);
    run_checked(&mut make, "build trusted gmp static library")?;

    copy_regular("gmp", &build.join("gmp.h"), &include.join("gmp.h"))?;
    copy_regular("gmp", &build.join(".libs/libgmp.a"), &library.join("libgmp.a"))?;

    let archive = library.join("libgmp.a");
    let mut inspect = request.toolchain.command(&request.toolchain.ar);
    inspect.arg("t").arg(&archive);
    run_checked(&mut inspect, "validate trusted gmp static archive")?;
    fs::remove_dir_all(&build)
        .map_err(|error| NativeError::io("remove trusted gmp build tree", &build, error))?;
    Ok(())
}

/// Returns the `configure` arguments for one target.
///
/// x86_64 uses GMP's fat binary so a `libgmp.a` cached from one runner still runs on
/// older CPUs without the instructions the build host selected.
fn configure_args(target: Target) -> Vec<&'static str> {
    let mut args = vec!["--disable-shared", "--enable-static", "--with-pic"];
    if target.arch == Arch::X86_64 {
        args.push("--enable-fat");
    }
    // GMP's aarch64 assembly uses GOT-relative ADRP sequences that the Darwin
    // integrated assembler rejects for the iOS platform variant. The generic C
    // implementation is complete, so iOS builds it instead.
    if matches!(
        target.apple_variant,
        AppleVariant::IOS | AppleVariant::IOSSimulator
    ) {
        args.push("--disable-assembly");
    }
    args
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Pins the archive and header locations this recipe depends on to a real GMP source
    /// layout. The paths are generated by configure/make, not committed, so a future
    /// upstream layout change must fail this test rather than silently copy nothing.
    #[test]
    fn gmp_output_paths_are_the_configured_build_layout() {
        assert_eq!(Path::new(".libs").join("libgmp.a"), Path::new(".libs/libgmp.a"));
        assert_eq!(Path::new("gmp.h"), Path::new("gmp.h"));
    }

    /// Verifies x86_64 builds use GMP's CPU-portable fat binary and ARM64 does not need it.
    #[test]
    fn x86_64_gmp_build_uses_the_fat_binary() {
        let x86_64 = Target {
            platform: crate::codegen_support::platform::Platform::Linux,
            arch: Arch::X86_64,
            apple_variant: crate::codegen_support::platform::AppleVariant::MacOS,
        };
        let aarch64 = Target {
            platform: crate::codegen_support::platform::Platform::Linux,
            arch: Arch::AArch64,
            apple_variant: crate::codegen_support::platform::AppleVariant::MacOS,
        };
        assert!(configure_args(x86_64).contains(&"--enable-fat"));
        assert!(!configure_args(aarch64).contains(&"--enable-fat"));

        let ios = Target {
            platform: crate::codegen_support::platform::Platform::MacOS,
            arch: Arch::AArch64,
            apple_variant: AppleVariant::IOS,
        };
        assert!(configure_args(ios).contains(&"--disable-assembly"));
        assert!(!configure_args(aarch64).contains(&"--disable-assembly"));
    }
}
